mapper.insert:
INSERT INTO video_play_segment (segment_id, session_id, segment, create_time, update_time)
VALUES (#{id.segmentId}, #{id.sessionId}, int4range(#{startWatchTimeInSeconds}, #{endWatchTimeInSeconds}), #{createTime}, #{updateTime})
ON CONFLICT (session_id, segment_id)
DO UPDATE SET segment = int4range(lower(video_play_segment.segment), #{endWatchTimeInSeconds}), update_time = #{updateTime}
    WHERE NOT video_play_segment.segment @> int4range(#{startWatchTimeInSeconds}, #{endWatchTimeInSeconds});

mapper.select:
SELECT time_bucket, SUM(upper(segment) - lower(segment)) AS value
    FROM generate_series(#{filter.start}, #{filter.end}, #{interval}::interval) AS time_bucket
    LEFT JOIN video_play_segment ON create_time >= time_bucket AND create_time < time_bucket + #{interval}::interval
    LEFT JOIN video_play_session ON video_play_session.id = video_play_segment.session_id AND master_id = #{masterId}
GROUP BY time_bucket
ORDER BY time_bucket;
